function calculateDockScale(cursorX, iconX, maxScale = 1.6, radius = 120) {
  const distance = Math.abs(cursorX - iconX);
  if (distance > radius) return 1;
  const factor = Math.cos((distance / radius) * (Math.PI / 2));
  return 1 + (maxScale - 1) * Math.pow(factor, 2);
}

class WindowManager {
  constructor() {
    this.activeZ = 100;
    this.windows = new Map();
  }
  focusWindow(winId) {
    this.activeZ++;
    const el = document.getElementById(winId);
    if (el) el.style.zIndex = this.activeZ;
  }
}

.macos-glass {
  background: rgba(30, 30, 30, 0.65);
  backdrop-filter: blur(24px) saturate(180%);
  -webkit-backdrop-filter: blur(24px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: 0 16px 32px 0 rgba(0, 0, 0, 0.37);
}

document.addEventListener('keydown', (e) => {
  if ((e.metaKey || e.ctrlKey) && e.code === 'Space') {
    e.preventDefault();
    toggleSpotlight();
  }
});
